Item.method_code:
string TargetRecDocName = "技-62";

Innovator inn = this.getInnovator();

var relItemID = this.getProperty("related_id","");
if(relItemID == ""){return this;}

var relatedItem = inn.newItem("h4_ReqDoc","get");
relatedItem.setProperty("id",relItemID);
relatedItem = relatedItem.apply();
if(relatedItem.isError())
{
    return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
}

if(relatedItem.getProperty("name","") == TargetRecDocName)
{
    
    this.setAction("edit");
    this.setAttribute("serverEvents","0");
    this.setAttribute("version","0");
    this.setProperty("sort_order","1");
    
    using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Administrators")))
    {
        var tmp = this.apply();
        if(tmp.isError())
        {
            return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002")); 
        }
    }
}
return this;
